#include <stdio.h>

void find_max_and_count(int arr[], int n, int *out_max, int *out_count) {
    // FIX 1: Initialize to first element, not 0
    int max_val = arr[0];
    int count = 1;

    // FIX 2: i < n, not i <= n
    for (int i = 1; i < n; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
            count = 1;
        } else if (arr[i] == max_val) {
            count++;
        }
    }

    *out_max = max_val;

}

int main() {
    int arr[] = {1, 5, 3, 5, 2};
    int n = sizeof(arr) / sizeof(arr[0]);
    int max_val, count;
    find_max_and_count(arr, n, &max_val, &count);
    printf("%d %d\n", max_val, count); // Expected: 5 2
    return 0;
}

