void find_max_and_count(int arr[], int n, int *out_max, int *out_count) {
    // BUG 1: Initializing max to 0 fails for all-negative arrays
    int max_val = 0;
    int count = 0;

    // BUG 2: Loop condition i <= n causes buffer over-read
    for (int i = 0; i <= n; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
            count = 1;
        } else if (arr[i] == max_val) {
            count++;
        }
    }

    *out_max = max_val;
    *out_count = count;
}

int main() {
